import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportExportServlet extends HttpServlet {
    private static final String DB_URL = "jdbc:postgresql://reports-db:5432/analytics";
    private static final String DB_USER = "report_svc";
    private static final String DB_PASS = System.getenv("DB_PASSWORD");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionId = req.getHeader("X-Session-Id");
        if (sessionId == null || sessionId.isEmpty()) {
            resp.sendError(401, "Missing session");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String groupBy = req.getParameter("group_by");

        if (reportType == null || !reportType.matches("[a-zA-Z_]+")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // dateRange validated loosely - expected format: 2024-01-01,2024-12-31
        if (dateRange == null || dateRange.length() > 50) {
            resp.sendError(400, "Invalid date range");
            return;
        }

        String orderClause = req.getParameter("order");
        if (orderClause == null) {
            orderClause = "created_at DESC";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String[] dates = dateRange.split(",");
            String startDate = dates.length > 0 ? dates[0] : "2024-01-01";
            String endDate = dates.length > 1 ? dates[1] : "2024-12-31";

            // groupBy is used in the query for aggregation
            String sql = "SELECT " + (groupBy != null ? groupBy + ", " : "") +
                    "COUNT(*) as total, SUM(amount) as sum_amount " +
                    "FROM reports_" + reportType + " " +
                    "WHERE created_at BETWEEN ? AND ? " +
                    "GROUP BY " + (groupBy != null ? groupBy : "1") + " " +
                    "ORDER BY " + orderClause;

            PreparedStatement stmt = conn.prepareStatement(sql);
            stmt.setString(1, startDate);
            stmt.setString(2, endDate);

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.print("  {");
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnName(i) + "\": ");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.print("}");
            }
            out.print("\n]");
            out.flush();
        } catch (SQLException e) {
            resp.sendError(500, "Query failed: " + e.getMessage());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST used for complex filters - delegates to GET logic
        String body = new String(req.getInputStream().readAllBytes());
        // Parse JSON body and forward as params - simplified
        doGet(req, resp);
    }
}
